-- AD4 CHECK (read-only): one row per rule, ok must be true on every row. Run through ad-sql-run.sh after AD4.sql.
SELECT 'both AD4 tables exist with RLS enabled and forced' AS rule, (SELECT count(*) FROM pg_class c JOIN pg_namespace s ON s.oid = c.relnamespace WHERE s.nspname = 'desk' AND c.relname IN ('fadm_lookup','fadm_lookup_field') AND c.relrowsecurity AND c.relforcerowsecurity) = 2 AS ok
UNION ALL SELECT 'lookup events are append-only (update, delete, truncate triggers)', (SELECT count(*) FROM pg_trigger WHERE tgrelid = 'desk.fadm_lookup'::regclass AND tgname IN ('fadm_lookup_frozen','fadm_lookup_frozen_t')) = 2
UNION ALL SELECT 'the field guard runs before the insert', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'desk.fadm_lookup'::regclass AND tgname = 'fadm_lookup_00guard')
UNION ALL SELECT 'closed list has the 18 contract fields', (SELECT count(*) FROM desk.fadm_lookup_field) >= 18
UNION ALL SELECT 'no field on the closed list can name money (amount, invoice, card, refund, transaction, iban, price, Polar, webhook)', NOT EXISTS (SELECT 1 FROM desk.fadm_lookup_field WHERE field ~* '(amount|invoice|card|cvv|refund|transaction|iban|bank|polar|webhook|price|payment_method)')
UNION ALL SELECT 'the field name rule is a constraint on the list', EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'desk.fadm_lookup_field'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) ILIKE '%invoice%')
UNION ALL SELECT 'a reason of 10 to 300 characters is a constraint', EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'desk.fadm_lookup'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) ILIKE '%300%')
UNION ALL SELECT 'the company is an opaque reference (constraint)', EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'desk.fadm_lookup'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) ILIKE '%company_ref%')
UNION ALL SELECT 'customer.lookup is an action with a deny-by-default policy for agents', EXISTS (SELECT 1 FROM desk.fadm_action WHERE action = 'customer.lookup') AND EXISTS (SELECT 1 FROM desk.fadm_policy WHERE name = 'p_customer_lookup' AND effect = 'permit' AND relation = 'agent')
UNION ALL SELECT 'bulk viewing breaker is 30 per minute', (SELECT max_per_min FROM desk.fadm_burst_limit WHERE action = 'customer.lookup') = 30
UNION ALL SELECT 'lookup ledger kinds are on the closed list', (SELECT count(*) FROM desk.fadm_ledger_kind WHERE kind IN ('lookup.company','lookup.unavailable')) = 2
UNION ALL SELECT 'desk_app has no direct right on the lookup tables', NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace s ON s.oid = c.relnamespace WHERE s.nspname = 'desk' AND c.relname IN ('fadm_lookup','fadm_lookup_field') AND (has_table_privilege('desk_app', c.oid, 'SELECT') OR has_table_privilege('desk_app', c.oid, 'INSERT') OR has_table_privilege('desk_app', c.oid, 'UPDATE') OR has_table_privilege('desk_app', c.oid, 'DELETE')))
UNION ALL SELECT 'the three lookup doors are granted to desk_app', has_function_privilege('desk_app', 'desk.fadm_lookup_begin(uuid,text,text,text[],uuid,inet)', 'EXECUTE') AND has_function_privilege('desk_app', 'desk.fadm_lookup_finish(uuid,uuid,text)', 'EXECUTE') AND has_function_privilege('desk_app', 'desk.fadm_lookup_history(uuid,text,integer,inet)', 'EXECUTE')
UNION ALL SELECT 'no PUBLIC execute on Desk functions', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'desk' AND p.proname LIKE 'fadm\_lookup%' AND has_function_privilege('public', p.oid, 'EXECUTE'))
UNION ALL SELECT 'all SECURITY DEFINER functions pin search_path', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'desk' AND p.prosecdef AND (p.proconfig IS NULL OR NOT EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%')))
UNION ALL SELECT 'desk_app is no superuser and does not bypass RLS', NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'desk_app' AND (rolsuper OR rolbypassrls))
UNION ALL SELECT 'every result row has its request row (no answer without a recorded request)', NOT EXISTS (SELECT 1 FROM desk.fadm_lookup a WHERE a.outcome <> 'requested' AND NOT EXISTS (SELECT 1 FROM desk.fadm_lookup r WHERE r.request_id = a.request_id AND r.outcome = 'requested'))
UNION ALL SELECT 'ledger hash chain still verifies', desk.fadm_ledger_verify();
